                r=copy.deepcopy(vt.BASE); mutate(r); raw=json.dumps(r).encode()+b"\n"
            p=subprocess.run([sys.executable,'/app/submission/planner.py'],input=raw,capture_output=True)
            print("=== ",nm,"->", p.stdout.decode().strip()[:150], "stderr:",p.stderr.decode()[:300])
            if p.stdout.decode().strip().startswith('{"status": "invalid"}'):
                # try to find the reason
                rr=json.loads(raw)
                try:
                    sys.path.insert(0,'/app/submission')
                    import planner as P
                    P.parse_request(raw[:-1])
                except Exception as e:
                    print("    reason:", repr(e))
            break
